/**
 * In-memory location search over a NormalizedNavGraph.
 * Case-insensitive prefix match on label, roomNumber, description, buildingName.
 * Results grouped by building → floor, sorted alphabetically/numerically.
 */

import { useMemo } from 'react';
import { NormalizedNavGraph } from '../domain/navGraph';
import { NavNodeType } from '../../src/shared/types';

export interface SearchNode {
  node: import('../../src/shared/types').NavNode;
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
}
export interface SearchFloor { floorId: number; floorNumber: number; nodes: SearchNode[]; }
export interface SearchBuilding { buildingId: number; buildingName: string; floors: SearchFloor[]; }
export interface UseLocationSearchResult { buildings: SearchBuilding[]; totalMatches: number; }

function isPrefixMatch(query: string, target: string): boolean {
  return query.length === 0 || target.toLowerCase().startsWith(query.toLowerCase());
}

export function useLocationSearch(
  graph: NormalizedNavGraph,
  query: string,
  typeFilter?: Set<NavNodeType>,
): UseLocationSearchResult {
  return useMemo(() => {
    const trimmed = query.trim();
    const buildings: SearchBuilding[] = [];
    let totalMatches = 0;

    for (const building of graph.graph.buildings) {
      const matchedFloors: SearchFloor[] = [];

      for (const floor of building.floors) {
        const floorRec = graph.floorById.get(floor.id);
        const floorNumber = floorRec?.floor.floorNumber ?? floor.floorNumber;
        const matchedNodes: SearchNode[] = [];

        for (const node of floor.nodes) {
          if (!node.searchable) continue;
          if (typeFilter && !typeFilter.has(node.type)) continue;
          if (trimmed.length > 0) {
            const labelOk = isPrefixMatch(trimmed, node.label);
            const roomOk = node.roomNumber && isPrefixMatch(trimmed, node.roomNumber);
            const descOk = node.description && isPrefixMatch(trimmed, node.description);
            const bldOk = isPrefixMatch(trimmed, building.name);
            if (!labelOk && !roomOk && !descOk && !bldOk) continue;
          }
          matchedNodes.push({ node, buildingId: building.id, buildingName: building.name, floorId: floor.id, floorNumber });
        }

        if (matchedNodes.length > 0) {
          matchedNodes.sort((a, b) => a.node.label.localeCompare(b.node.label));
          matchedFloors.push({ floorId: floor.id, floorNumber, nodes: matchedNodes });
          totalMatches += matchedNodes.length;
        }
      }

      if (matchedFloors.length > 0) {
        matchedFloors.sort((a, b) => a.floorNumber - b.floorNumber);
        buildings.push({ buildingId: building.id, buildingName: building.name, floors: matchedFloors });
      }
    }

    buildings.sort((a, b) => a.buildingName.localeCompare(b.buildingName));
    return { buildings, totalMatches };
  }, [graph, query, typeFilter]);
}

/**
 * Guidance session orchestrator — wires useRouteSession, useCurrentPosition,
 * and the guidance state machine into a live guidance loop.
 *
 * Responsibilities:
 * - Subscribes to GPS + heading via useCurrentPosition
 * - Projects lat/lng → normalized map coords → nearest walkable node
 * - Drives phase transitions (idle → guiding → rerouting → arrived)
 * - Advances currentStepIndex as the user progresses
 * - Triggers reroute via MobilePathfindingEngine when off-route
 * - Exposes manual confirmPosition() for user-asserted location
 */

import { useCallback, useEffect, useRef, useState } from 'react';

import {
  projectLatLngToNormalizedPoint,
  snapLatLngToNearestWalkableNode,
} from '../../src/shared/gps';
import {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
} from '../domain/navGraph';
import {
  deriveConfidence,
  isOffRoute,
  shouldAdvanceStep,
} from '../routing/guidanceState';
import {
  ConfidenceLevel,
  GuidancePhase,
  GuidanceState,
  HeadingFix,
  PositionFix,
} from '../routing/guidanceState';
import { MobilePathfindingEngine } from '../routing/pathfindingEngine';
import { RouteSessionReadyState } from '../routing/routeSessionState';
import { useCurrentPosition } from './useCurrentPosition';
import {
  HeadingData,
  PositionFix as HookPositionFix,
} from './useCurrentPosition';

// ============================================================
// Props
// ============================================================

export interface UseGuidanceSessionProps {
  /** Normalized navigation graph (from useRouteSelection). */
  graph: NormalizedNavGraph;
  /** Ready route from useRouteSession (S02). Must have phase === 'ready'. */
  route: RouteSessionReadyState;
  /** Minimum ms between position updates. Default: 2000. */
  updateIntervalMs?: number;
  /** Off-route threshold in normalized map units. Default: 0.05. */
  offRouteThreshold?: number;
  /** Consecutive off-route fixes needed before reroute. Default: 2. */
  rerouteConfirmFixes?: number;
  /** Minimum ms between reroute triggers. Default: 5000. */
  rerouteCooldownMs?: number;
  /** Max accuracy (m) for confident GPS fix. Default: 50. */
  maxAccuracyMeters?: number;
}

// ============================================================
// Result
// ============================================================

export interface UseGuidanceSessionResult {
  /** Live guidance state snapshot (use for React rendering). */
  guidanceState: GuidanceState;
  /**
   * Begin live guidance from the current GPS position.
   * Snaps to the nearest walkable node and transitions phase.
   */
  startGuidance: () => void;
  /** Halt live guidance and return to idle. */
  stopGuidance: () => void;
  /**
   * User asserts their location by tapping a node on the map.
   * Resets offRouteFixCount and re-derives confidence.
   */
  confirmPosition: (nodeId: string) => void;
}

// ============================================================
// Pure helpers (extracted for testability)
// ============================================================

/** Convert useCurrentPosition fix → guidance state PositionFix */
export function hookFixToStateFix(fix: HookPositionFix | null): PositionFix {
  if (!fix) {
    return { isConfident: false, accuracyMeters: null };
  }
  return {
    isConfident: fix.accuracyMeters != null && isFinite(fix.accuracyMeters),
    accuracyMeters: fix.accuracyMeters,
  };
}

/** Convert useCurrentPosition heading → guidance state HeadingFix */
export function hookHeadingToStateHeading(
  heading: HeadingData | null,
): HeadingFix {
  if (!heading) {
    return { headingDegrees: null, accuracyDegrees: null };
  }
  return {
    headingDegrees: heading.headingDegrees,
    accuracyDegrees: heading.accuracyDegrees,
  };
}

