  promise: Promise<T>,
  timeoutMs: number,
  signal?: AbortSignal,
): Promise<T> {
  // If the signal is already aborted, reject immediately rather than racing
  // against the timeout — prevents a timeout-triggered rejection when the caller
  // already cancelled the request.
  if (signal?.aborted) {
    return Promise.reject(makeAbortError());
